<?php
namespace App\Http\Controllers;
use App\Http\Requests\StoreMemberRequest;use App\Models\{Household,Member,MinistryGroup};use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Inertia\{Inertia,Response};
class MemberController extends Controller {
 //public function __construct(){ $this->authorizeResource(Member::class,'member'); }
 public function index(Request $request):Response{$members=Member::query()->with(['household:id,name','ministryGroups:id,name'])->search((string)$request->string('search'))->when($request->status,fn($q,$v)=>$q->where('status',$v))->when($request->gender,fn($q,$v)=>$q->where('gender',$v))->when($request->joined_from,fn($q,$v)=>$q->whereDate('join_date','>=',$v))->when($request->joined_to,fn($q,$v)=>$q->whereDate('join_date','<=',$v))->orderBy(in_array($request->input('sort'),['first_name','last_name','join_date','status'],true)?$request->input('sort'):'last_name',$request->input('direction')==='desc'?'desc':'asc')->paginate(15)->withQueryString();return Inertia::render('Members/Index',['members'=>$members,'filters'=>$request->only('search','status','gender','joined_from','joined_to','sort','direction')]);}
 public function create():Response{return Inertia::render('Members/Form',['member'=>null,'households'=>Household::orderBy('name')->get(['id','name']),'ministryGroups'=>MinistryGroup::where('status','active')->orderBy('name')->get(['id','name'])]);}
 public function store(StoreMemberRequest $request):RedirectResponse{$member=DB::transaction(function()use($request){$data=$request->safe()->except('ministry_group_ids');$m=Member::create($data);$m->ministryGroups()->sync($request->input('ministry_group_ids',[]));return $m;});return redirect()->route('members.show',$member)->with('success','Member created successfully.');}
 public function show(Request $request,Member $member):Response{$member->load(['household','ministryGroups','attendanceRecords'=>fn($q)=>$q->latest('attendance_date')->limit(20),'donations'=>fn($q)=>$q->latest('donation_date')->limit(20),'communications'=>fn($q)=>$q->latest('sent_at')->limit(20)]);if($request->user()->can('viewAny',\App\Models\PastoralNote::class))$member->load(['pastoralNotes'=>fn($q)=>$q->with('author:id,name')->latest('note_date')]);return Inertia::render('Members/Show',['member'=>$member,'can'=>['edit'=>$request->user()->can('update',$member),'delete'=>$request->user()->can('delete',$member),'viewPastoralNotes'=>$request->user()->can('viewAny',\App\Models\PastoralNote::class)]]);}
 public function edit(Member $member):Response{$member->load('ministryGroups:id');return Inertia::render('Members/Form',['member'=>$member,'households'=>Household::orderBy('name')->get(['id','name']),'ministryGroups'=>MinistryGroup::where('status','active')->orderBy('name')->get(['id','name'])]);}
 public function update(StoreMemberRequest $request,Member $member):RedirectResponse{DB::transaction(function()use($request,$member){$member->update($request->safe()->except('ministry_group_ids'));$member->ministryGroups()->sync($request->input('ministry_group_ids',[]));});return redirect()->route('members.show',$member)->with('success','Member updated successfully.');}
 public function destroy(Member $member):RedirectResponse{$member->delete();return redirect()->route('members.index')->with('success','Member archived.');}
}
